def maxValue(nums):
    n = len(nums)
    prefmax = [0] * n
    prefmax[0] = nums[0]
    for i in range(1, n):
        prefmax[i] = max(prefmax[i - 1], nums[i])

    sufmin = [0] * n
    sufmin[n - 1] = nums[n - 1]
    for i in range(n - 2, -1, -1):
        sufmin[i] = min(sufmin[i + 1], nums[i])

    ans = [0] * n
    ans[n - 1] = prefmax[n - 1]  # global maximum
    for i in range(n - 2, -1, -1):
        if prefmax[i] > sufmin[i + 1]:
            ans[i] = ans[i + 1]   # the two sides are mutually reachable
        else:
            ans[i] = prefmax[i]   # nothing crosses the boundary
    return ans
